arguments.command:
curl -s -X POST "https://slack.com/api/users.conversations" -d 'token=<TOKEN>' -d 'types=private_channel' -d 'exclude_archived=true' -d 'limit=999' > /tmp/slack_convs.json; python3 -c "
import json
d=json.load(open('/tmp/slack_convs.json'))
if not d.get('ok'):
    print('ERROR', d); raise SystemExit(1)
for c in d['channels']:
    p=c.get('purpose',{}).get('value','')
    if 'ship the spring release' in p.lower():
        print(c['id'], repr(c.get('name')), 'purpose:', repr(p), 'is_private:', c.get('is_private'))
"

